import re
from typing import Union


def evaluate_expression(expression: str) -> float:
    """Evaluate an arithmetic expression such as "2 * (3 + 4) - 1.5" and return the
    result as a float. Numbers, parentheses, unary minus and the operators + - * / **
    are supported. Raise ValueError for malformed input such as "2 +" or an empty string.
    """
    if not expression or not expression.strip():
        raise ValueError("Empty expression")

    expression = expression.strip()

    tokens = tokenize(expression)

    if not tokens:
        raise ValueError("Empty expression")

    result, pos = parse_expression(tokens, 0)

    if pos != len(tokens):
        raise ValueError(f"Unexpected token at position {pos}")

    return result


def tokenize(expression: str) -> list:
    """Tokenize the expression into numbers, operators, and parentheses."""
    token_pattern = r'(\d+\.?\d*|\.\d+|[+\-*/()**])'
    tokens = re.findall(token_pattern, expression)

    if not tokens:
        raise ValueError("Invalid expression")

    # Validate that tokens form a valid expression
    reconstructed = ''.join(tokens)
    if reconstructed.replace(' ', '') != expression.replace(' ', ''):
        raise ValueError("Invalid characters in expression")

    return tokens


def parse_expression(tokens: list, pos: int) -> tuple[float, int]:
    """Parse an expression (handles + and -)."""
    left, pos = parse_term(tokens, pos)

    while pos < len(tokens) and tokens[pos] in ('+', '-'):
        op = tokens[pos]
        pos += 1
        right, pos = parse_term(tokens, pos)
        if op == '+':
            left = left + right
        else:
            left = left - right

    return left, pos


def parse_term(tokens: list, pos: int) -> tuple[float, int]:
    """Parse a term (handles * and /)."""
    left, pos = parse_power(tokens, pos)

    while pos < len(tokens) and tokens[pos] in ('*', '/'):
        op = tokens[pos]
        pos += 1
        right, pos = parse_power(tokens, pos)
        if op == '*':
            left = left * right
        else:
            if right == 0:
                raise ValueError("Division by zero")
            left = left / right

    return left, pos


def parse_power(tokens: list, pos: int) -> tuple[float, int]:
    """Parse power expressions (handles **)."""
    left, pos = parse_unary(tokens, pos)

    if pos < len(tokens) and tokens[pos] == '**':
        pos += 1
        right, pos = parse_power(tokens, pos)
        left = left ** right

    return left, pos


def parse_unary(tokens: list, pos: int) -> tuple[float, int]:
    """Parse unary expressions (handles unary minus)."""
    if pos >= len(tokens):
        raise ValueError("Unexpected end of expression")

    if tokens[pos] == '-':
        pos += 1
        value, pos = parse_unary(tokens, pos)
        return -value, pos
    elif tokens[pos] == '+':
        pos += 1
        return parse_unary(tokens, pos)
    else:
        return parse_primary(tokens, pos)


def parse_primary(tokens: list, pos: int) -> tuple[float, int]:
    """Parse primary expressions (numbers and parentheses)."""
    if pos >= len(tokens):
        raise ValueError("Unexpected end of expression")

    token = tokens[pos]

    if token == '(':
        pos += 1
        result, pos = parse_expression(tokens, pos)
        if pos >= len(tokens) or tokens[pos] != ')':
            raise ValueError("Missing closing parenthesis")
        pos += 1
        return result, pos

    try:
        value = float(token)
        return value, pos + 1
    except ValueError:
        raise ValueError(f"Invalid token: {token}")
